async function removeProviderProfile(operations, controller, target) {
  // DSHA_MODEL_DELETE_KEEP_SHARED_KEY_V1: a provider is profile-local; its saved key can be reused by other profiles.
  const revision = controller.store.getSnapshot().namespaces.get(target.settingsNs)?.revision;
  const written = await operations.writeSettings(target.settingsNs, [{ op: `unset`, path: [...target.settingsPath] }], revision);
  if (written.kind !== `written`) return written.message;
  await controller.load();
}
